CREATE VIRTUAL TABLE t1 USING fts4(x); INSERT INTO t1(docid,x) VALUES(-2,'a b c d e f g h i j k'),(-1,'b c d e f g h i j k a'),(0,'c d e f g h i j k a b'),(1,'d e f g h i j k a b c'),(2,'e f g h i j k a b c d'),(3,'f g h i j k a b c d e'),(4,'a c e g i k'),(5,'a d g j'),(6,'c a b'); BEGIN; WITH RECURSIVE n(i) AS (VALUES(0) UNION ALL SELECT i+1 FROM n WHERE i<442) INSERT INTO t1(x) SELECT replace(hex(zeroblob(100)),'00','c ') FROM n; INSERT INTO t1(x) VALUES('aaaaaaa caaaaa'); COMMIT; UPDATE t1_segments SET block=zeroblob(length(block)) WHERE length(block)>36864;